import React, { useEffect, useRef, useState } from 'react';
import { SafeAreaView, ScrollView, View, ImageBackground, KeyboardAvoidingView, Image, Dimensions, Animated, Alert } from 'react-native';
import { ActionButton, GradientButton, LoadingBlockerView, SimpleHeader, Spacer, Text, useTheme } from '@core/ui';
import useCSS from '@src/presentation/style';
import { useNavigation } from '@react-navigation/native';
import { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import { useDispatch, useSelector } from '@src/lib/redux';
import { useTranslation } from 'react-i18next';
import getImg from '@src/utils/getImg';
import { IS_IOS, STORAGE_KEY, Storage } from '@core/service';
import { fetchCardListAvailable } from './thunk';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import { CardListAvailableDataReq } from '@src/domain/entities/card_dop/cardListAvailable';
import { selectCardList, selectError, selectStatus } from './DOPHomeSelector';
import DOPHomeSlice from './DOPHomeSlice';
import { fetchLocationDetail } from '../weather/WeatherSearch';
const { width } = Dimensions.get('window');
const CARD_WIDTH = width * 0.85; // Giảm chiều rộng để hiển thị một phần item tiếp theo
const SPACING = 16; // Khoảng cách giữa các item

const DOPHomeScreen = () => {
    const error = useSelector(selectError);
    const status = useSelector(selectStatus);
    const css = useCSS();
    const dispatch = useDispatch();
    const navigation = useNavigation<MainStackNavigationProp>();
    const { t } = useTranslation(['home']);
    const disabled = false;
    const { theme } = useTheme();
    const [activeIndex, setActiveIndex] = useState(0);
    const scrollViewRef = useRef(null);
    const scrollX = useRef(new Animated.Value(0)).current;

    const handleScroll = (event: any) => {
        const offsetX = event.nativeEvent.contentOffset.x;
        const newIndex = Math.round(offsetX / CARD_WIDTH);
        setActiveIndex(newIndex);
    };

    const cardList = useSelector(selectCardList);

    const handleSubmit = () => {
        if (cardList?.length > 0 && cardList[activeIndex]) {
            dispatch(DOPHomeSlice.actions.setCardActive(cardList[activeIndex]));
            navigation.navigate('DOP_CVP');
        }
    };

    useEffect(() => {
        if (error) {
            Alert.alert('Thông báo', error);
        }
    }, [error]);

    // useEffect(() => {
    //     dispatch(fetchLocationDetail('test')).then((res) => {
    //         if (!(res.payload as any)?.data?.accessToken) {
    //             Alert.alert('Thông báo', 'Lỗi không xác định');
    //         } else {
    //             // dispatch(cardSlice.actions.setToken((res.payload as any)?.data?.token))
    //             Storage.save(STORAGE_KEY.USER_AUTH, (res.payload as any)?.data);
    //         }
    //     });
    // }, []);

    useEffect(() => {
        dispatch(fetchCardListAvailable({} as CardDOPBaseRequest<CardListAvailableDataReq>['data']));
    }, []);


    return (
        <KeyboardAvoidingView behavior={IS_IOS ? 'padding' : 'height'} style={[css.flex_1]}>
            <ImageBackground source={getImg('/assets/images/bg_body.jpg')} resizeMode='cover' style={{ flex: 1 }}>
                <SafeAreaView style={[css.flex_1]}>
                    <SimpleHeader
                        allowGoBack
                        title={t('header_title')}
                        onBackPress={() => {
                            navigation.goBack();
                        }}
                    />
                    {status === 'loading' ? (
                        <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} />
                    ) : cardList.length > 0 ? (
                        <View style={[css.flex_1]}>
                            <Text style={[css.text_title_200, css.font_semibold, css.text_black, css.mt_xLarge, css.mh_medium]}>{t('title')}</Text>
                            <ScrollView
                                ref={scrollViewRef}
                                style={[css.mt_xLarge]}
                                horizontal
                                pagingEnabled={false} // Tắt pagingEnabled để có hiệu ứng trượt mượt
                                showsHorizontalScrollIndicator={false}
                                onScroll={Animated.event([{ nativeEvent: { contentOffset: { x: scrollX } } }], {
                                    useNativeDriver: false,
                                    listener: handleScroll,
                                })}
                                snapToInterval={CARD_WIDTH + SPACING}
                                decelerationRate='fast'
                                scrollEventThrottle={16}>
                                {cardList?.map((item, index) => (
                                    <View key={`${item?.productCode}-${index}`} style={[{ marginLeft: SPACING }]}>
                                        <View
                                            style={[
                                                { width: CARD_WIDTH },
                                                css.min_h_full,
                                                css.rounded_xLarge,
                                                css.bg_white,
                                                css.overflow_hidden,
                                                css.relative,
                                            ]}>
                                            <Image
                                                resizeMode='stretch'
                                                source={getImg('/assets/images/bg/bg_header_Loan_registration_card.png')}
                                                style={[
                                                    css.w_full,
                                                    css.rounded_tl_xLarge,
                                                    css.rounded_tr_xLarge,
                                                    {
                                                        height: theme.Scaling.vs(100),
                                                    },
                                                ]}
                                            />
                                            <Image
                                                resizeMode='stretch'
                                                source={getImg('/assets/images/bg/bg_confetti.png')}
                                                style={[
                                                    css.absolute,
                                                    css.w_full,
                                                    css.rounded_tl_xLarge,
                                                    css.rounded_tr_xLarge,
                                                    {
                                                        top: 0,
                                                        left: 0,
                                                        height: theme.Scaling.vs(200),
                                                    },
                                                ]}
                                            />
                                            <View style={[css.mh_xLarge]}>
                                                <View style={[css.row, css.items_start]}>
                                                    <Image
                                                        resizeMode='contain'
                                                        source={{ uri: item.image }}
                                                        style={[
                                                            css.mr_base,
                                                            {
                                                                width: theme.Scaling.hs(81),
                                                                height: theme.Scaling.vs(105),
                                                                marginTop: -theme.Size.Vertical.xxxLarge,
                                                            },
                                                        ]}
                                                    />
                                                    <Text
                                                        style={[
                                                            css.flex_1,
                                                            css.text_red_600,
                                                            css.text_title_300,
                                                            css.font_bold,
                                                            css.mt_base,
                                                            { lineHeight: theme.Scaling.vs(26) },
                                                        ]}>
                                                        {item.productName} {index}
                                                    </Text>
                                                </View>

                                                <View style={[css.mt_medium]}>
                                                    {item?.promoList.map((pro, i) => (
                                                        <View key={`promo-${i}`} style={[css.row, css.items_center, css.pv_base]}>
                                                            <Image
                                                                resizeMode='contain'
                                                                source={{ uri: pro.icon }}
                                                                style={[
                                                                    css.shrink_0,
                                                                    css.mr_medium,
                                                                    css.ratio_square,
                                                                    { width: theme.Scaling.hs(38), height: theme.Scaling.vs(38) },
                                                                ]}
                                                            />
                                                            <View style={[css.flex_1]}>
                                                                <Text style={[css.text_body, css.font_medium, css.text_black]}>{pro.title}</Text>
                                                                <Text style={[css.text_caption_100, css.font_regular, css.text_neutral_600, css.mt_small]}>
                                                                    {pro.detail}
                                                                </Text>
                                                            </View>
                                                        </View>
                                                    ))}
                                                </View>
                                                <Spacer height={24} />
                                            </View>
                                        </View>
                                    </View>
                                ))}
                            </ScrollView>
                            <View style={[css.row, css.justify_center, css.mt_xLarge]}>
                                {cardList.map((_, index) => (
                                    <View
                                        key={index}
                                        style={[
                                            css.mh_small,
                                            css.rounded_full,
                                            css.w_base,
                                            css.h_base,
                                            index === activeIndex ? css.bg_red_600 : css.bg_neutral_300,
                                        ]}
                                    />
                                ))}
                            </View>
                            <View style={[css.mt_auto, css.p_medium]}>
                                {disabled ? (
                                    <ActionButton title={t('button_label')} state={'disabled'} />
                                ) : (
                                    <GradientButton title={t('button_label')} gradientProps={{ type: 'primary' }} onPress={handleSubmit} />
                                )}
                            </View>
                        </View>
                    ) : (
                        <View style={[css.flex_1, css.justify_center, css.items_center]}>
                            <Text style={[css.text_center]}>Không có dữ liệu</Text>
                        </View>
                    )}
                </SafeAreaView>
            </ImageBackground>
        </KeyboardAvoidingView>
    );
};

export default DOPHomeScreen;
