import React, { useEffect, useRef, useState } from 'react';
import { SafeAreaView, ScrollView, View, ImageBackground } from 'react-native';
import { useTranslation } from 'react-i18next';
import { LoadingBlockerView, DynamicHeader, Spacer, Text, createStyles } from '@core/ui';
import { useNavigation } from '@react-navigation/native';
import { useSelector } from '@src/lib/redux';
import { selectICData } from '../dop_ocr/redux/selector';
import useCSS from '@src/presentation/style';
import { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import { HDBankLogoDash } from '@src/assets/images/icons';
import PinInputWrapper from './components/PinInputWrapper';

const DOPPinScreen = () => {
    const styles = useStyles();
    const css = useCSS();
    const { t } = useTranslation(['module_dop']);
    const navigation = useNavigation<MainStackNavigationProp>();

    const ICData = useSelector(selectICData);
    const { phoneNumber, dateOfBirth }: any = ICData;
    const formattedDateOfBirth = dateOfBirth?.replace(/\D/g, '');

    const [status, setStatus] = useState('idle');
    const [errorPin, setErrorPin] = useState<string>('');
    const [flagReset, setFlagReset] = useState(false);

    const pinInputRef = useRef<any>(null);

    useEffect(() => {
        setTimeout(() => {
            pinInputRef.current?.focus();
        }, 100);
    }, []);

    const handleOnSubmit = (pin: string) => {
        const [isValid, errorMessage] = validatePin(pin, formattedDateOfBirth, phoneNumber);
        if (isValid) {
            setErrorPin('');
            navigation.navigate('confirm_pin_screen', { pin });
        } else {
            setErrorPin(typeof errorMessage === 'string' ? errorMessage : '');
            setFlagReset((prev) => !prev);
        }
    };

    const validatePin = (pin: string, dateOfBirth?: string, phoneNumber?: string) => {
        const allSameDigits = /^(\d)\1{5}$/;
        if (allSameDigits.test(pin)) {
            return [false, t('screen_password.error_pin_all_same')];
        }

        const sequentialDigitsAsc = '0123456789';
        const sequentialDigitsDesc = '9876543210';
        if (sequentialDigitsAsc.includes(pin) || sequentialDigitsDesc.includes(pin)) {
            return [false, t('screen_password.error_pin_consecutive')];
        }

        if (dateOfBirth) {
            const dobPatterns = [
                dateOfBirth.slice(0, 2) + dateOfBirth.slice(2, 4) + dateOfBirth.slice(-2), // ddmmyy
                dateOfBirth.slice(2, 4) + dateOfBirth.slice(0, 2) + dateOfBirth.slice(-2), // mmddyy
                dateOfBirth.slice(-2) + dateOfBirth.slice(0, 2) + dateOfBirth.slice(2, 4), // yymmdd
                dateOfBirth.slice(-2) + dateOfBirth.slice(2, 4) + dateOfBirth.slice(0, 2), // yyddmm
            ];
            if (dobPatterns.includes(pin)) {
                return [false, t('screen_password.error_pin_dob')];
            }
        }

        if (phoneNumber && phoneNumber.length >= 6) {
            const phoneStart = phoneNumber.slice(0, 6);
            const phoneEnd = phoneNumber.slice(-6);

            if (pin === phoneStart || pin === phoneEnd) {
                return [false, t('screen_password.error_pin_phone_start_end')];
            }
        }

        const repeatedChars = /(.)\1{2,}/;
        if (repeatedChars.test(pin)) {
            return [false, t('screen_password.error_pin_repeated_chars')];
        }

        const hasSequentialDigits = (pin: string) => {
            for (let i = 0; i < pin.length - 2; i++) {
                const first = parseInt(pin[i]);
                const second = parseInt(pin[i + 1]);
                const third = parseInt(pin[i + 2]);

                if ((second === first + 1 && third === second + 1) || (second === first - 1 && third === second - 1)) {
                    return true;
                }
            }
            return false;
        };

        if (hasSequentialDigits(pin)) {
            return [false, t('screen_password.error_pin_sequential')];
        }

        return [true, ''];
    };

    return (
        <ImageBackground source={require('@src/assets/images/bg_body.jpg')} resizeMode='cover' style={[css.flex_1]}>
            <SafeAreaView style={[css.flex_1]}>
                <DynamicHeader
                    onBackPress={() => {
                        navigation.goBack();
                    }}
                    MainComponent={() => (
                        <View style={styles.mainContainer}>
                            <HDBankLogoDash style={styles.mainLogo} />
                        </View>
                    )}
                />
                {status === 'loading' ? <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> : null}
                <ScrollView showsHorizontalScrollIndicator={false} showsVerticalScrollIndicator={false}>
                    <View style={[css.flex_1, css.mt_xLarge, css.mh_medium]}>
                        <Text style={[css.text_title_200, css.font_semibold, css.text_black]}>
                            {t('screen_password.create')}{' '}
                            <Text style={[css.text_title_200, css.font_semibold, css.text_red_600]}>{t('screen_password.pin')}</Text>{' '}
                            {t('screen_password.to_login')}
                        </Text>
                        <Spacer height={8} />
                        <Text style={[css.text_subheadline, css.text_black]}>{t('screen_password.sub_title_pin')}.</Text>
                        <Spacer height={64} />
                        <View style={[css.w_full, css.items_center]}>
                            <PinInputWrapper ref={pinInputRef} cellCount={6} onSubmit={handleOnSubmit} isMask={true} flagReset={flagReset} />
                            <Spacer height={16} />
                            <Text style={[css.text_subheadline, css.text_red_600, css.text_center]}>{errorPin}</Text>
                        </View>
                        <Spacer height={64} />
                    </View>
                </ScrollView>
            </SafeAreaView>
        </ImageBackground>
    );
};

export default DOPPinScreen;

const useStyles = createStyles((theme) => ({
    mainContainer: {
        flex: 1,
        alignItems: 'center',
        justifyContent: 'center',
        gap: theme.Size.Horizontal.Regular,
        height: theme.Size.Vertical.xxxLarge,
    },
    mainLogo: {
        height: theme.Size.Vertical.xxxLarge,
    },
    container: {
        flexDirection: 'row',
        alignItems: 'center',
        backgroundColor: theme.Colors.Background.White,
        padding: theme.Size.Horizontal.Regular,
        borderRadius: theme.BorderRadius.md,
        borderColor: theme.Colors.Border.Neutral300,
        borderWidth: theme.Size.ms(1),
    },
    icon: {
        marginRight: theme.Size.Horizontal.Regular,
    },
    text: {
        ...theme.Typography.TextBody.Regular,
        flex: 1,
    },
}));
