import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_CARD_DOP_API } from '@src/config';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { IConfirmCardInfoRepository } from '@src/domain/interfaces/card_dop/confirmCardInfo';
import { ConfirmCardInfoDataReq, ConfirmCardInfoDataRes } from '@src/domain/entities/card_dop/confirmCardInfo';

@injectable()
export class ConfirmCardInfoRepository
    extends HttpService
    implements IConfirmCardInfoRepository {
    constructor() {
        super({ baseURL: BASE_URL_CARD_DOP_API });
    }

    async confirmCardInfo<TParameter>(query: Query<TParameter>): Promise<CardDOPBaseResponse<ConfirmCardInfoDataRes>> {
        const request = query.query as unknown as ConfirmCardInfoDataReq;        
        const url = '/dop-confirm-card-info';                
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-dop-mobile' }),
        })        
        console.log('\x1b[31m thieuvq3 response: ', response);
        return response.data as CardDOPBaseResponse<ConfirmCardInfoDataRes>;
    }
}
