import { View, TouchableOpacity } from 'react-native';
import React, { useEffect, useRef } from 'react';
import { BottomSheet, BottomSheetManager, BottomSheetRef, RadioButton, Text } from '@core/ui';
import useCSS from '@src/presentation/style';
import { FlatList } from 'react-native-gesture-handler';

interface Props<T extends object> {
    show: boolean;
    data: T[];
    keyValue: keyof T;
    keyLabel: keyof T;
    itemActive: T;
    onSelected: (item: T) => void;
    title: string;
    desc: string;
    onClose: () => void;
}
const BottomSheetRadios = <T extends object>({ show, data, keyValue, itemActive, keyLabel, onSelected, title, desc, onClose }: Props<T>) => {
    const css = useCSS();
    const bsRef = useRef<BottomSheetRef>(null);

    const handleSelected = (item: T) => {
        bsRef.current?.close();
        onSelected?.(item);
    };
    const renderItem = ({ item, index }: { item: T; index: number }) => {
        return (
            <>
                <TouchableOpacity onPress={() => handleSelected(item)} style={[css.pv_medium, index > 0 && [css.border_t_1, css.border_t_neutral_300]]}>
                    <View style={[css.row, css.justify_between, css.items_center]}>
                        <Text style={[css.flex_1, css.text_body, css.text_black, css.pr_regular]} numberOfLines={1}>
                            {item[keyLabel] as string}
                        </Text>
                        <RadioButton text='' onPress={() => handleSelected(item)} size='large' checked={item[keyValue] === itemActive[keyValue]} />
                    </View>
                </TouchableOpacity>
            </>
        );
    };
    const renderBottomSheet = () => {
        BottomSheetManager.show({
            render: (portalId) => (
                <BottomSheet ref={bsRef} id={portalId} title={title} description={desc} onClose={onClose} snapPoints={['70%']}>
                    <FlatList
                        showsHorizontalScrollIndicator={false}
                        showsVerticalScrollIndicator={false}
                        data={data}
                        pagingEnabled={false}
                        horizontal={false}
                        renderItem={renderItem}
                        contentContainerStyle={[css.pb_medium]}
                        keyExtractor={(item) => 'key_' + item[keyValue]}
                    />
                </BottomSheet>
            ),
        });
    };

    useEffect(() => {
        if (show) {
            renderBottomSheet();
        }
    }, [show]);

    return null;
};

export default BottomSheetRadios;
