import { Query } from '@src/domain/models/query';
import { createAsyncThunk } from '@reduxjs/toolkit';
import { TYPES } from '@src/di/types/types';
import { container } from '@src/di/inversify.config';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { GetAuthPublicKeyHandler } from '@src/application/card_dop/GetAuthPublicKey_handler';
import { GetAuthPublicKeyDataReq } from '@src/domain/entities/card_dop/getAuthPublicKey';
import { AuthUserHandler } from '@src/application/card_dop/authUser_handler';
import { AuthUserDataReq } from '@src/domain/entities/card_dop/authUser';

export const fetchGetAuthPublicKey = createAsyncThunk('getAuthPublicKey/fetch', async (payload: CardDOPBaseRequest<GetAuthPublicKeyDataReq>['data']) => {
    const getAuthPublicKey = container.get<GetAuthPublicKeyHandler>(TYPES.GetAuthPublicKeyHandler);    
    const payloadReq = commonService.getPayload<CardDOPBaseRequest<GetAuthPublicKeyDataReq>, CardDOPBaseRequest<GetAuthPublicKeyDataReq>['data']>({ data: payload })    
    const query = new Query<CardDOPBaseRequest<GetAuthPublicKeyDataReq>>({
        query: {            
            ...payloadReq,
            screenName:"MFE-DOP-LoginScreen",            
        },
    });
    return await getAuthPublicKey.handle(query);
});

