import React, { forwardRef, useEffect, useImperativeHandle, useRef, useState } from 'react';
import { PinInput, PinInputRef } from '@core/ui';
import { View, StyleProp, ViewStyle, KeyboardTypeOptions, TextStyle } from 'react-native';

interface PinInputWrapperProps {
    style?: StyleProp<ViewStyle>;
    cellCount: number;
    onSubmit: (pin: string) => void;
    isMask?: boolean;
    onPinSubmit?: (pin: string) => void;
    keyboardType?: KeyboardTypeOptions;
    isAutoFocus?: boolean;
    disabled?: boolean;
    errorText?: string;
    errorTextStyle?: TextStyle | TextStyle[] | undefined;
    flagReset?: boolean;
}

const PinInputWrapper = forwardRef<PinInputRef, PinInputWrapperProps>(
    (
        {
            onPinSubmit,
            style,
            cellCount,
            onSubmit,
            isMask,
            keyboardType,
            isAutoFocus,
            disabled,
            errorText,
            errorTextStyle,
            flagReset,
            ...rest
        }: PinInputWrapperProps,
        ref,
    ) => {
        const pinInputRef = useRef<PinInputRef>(null);
        const [pinValue, setPinValue] = useState('');

        useImperativeHandle(
            ref,
            () => ({
                focus: () => {
                    pinInputRef.current?.focus();
                },
                clear: () => {
                    pinInputRef.current?.clear();
                    setPinValue('');
                },
                setValue: (value) => {
                    pinInputRef.current?.setValue(value);
                    setPinValue(value);
                },
                hide: () => {
                    pinInputRef.current?.hide();
                },
            }),
            [],
        );

        useEffect(() => {
            setPinValue('');
        }, [flagReset]);

        const handleOnSubmit = (pin: string) => {
            if (onPinSubmit) {
                onPinSubmit(pin);
            }
        };

        const handleOnChange = (text: string) => {
            setPinValue(text);
        };

        return (
            <View>
                <PinInput
                    editable={!disabled}
                    ref={pinInputRef}
                    style={style}
                    cellCount={cellCount}
                    onSubmit={(pin) => {
                        onSubmit(pin);
                        handleOnSubmit(pin);
                    }}
                    onChange={handleOnChange} // Sử dụng onChange thay vì onChangeText
                    isMask={isMask}
                    value={pinValue}
                    keyboardType={keyboardType}
                    isAutoFocus={isAutoFocus}
                    errorText={errorText}
                    errorTextStyle={errorTextStyle}
                    {...rest}
                />
            </View>
        );
    },
);

export default PinInputWrapper;
