import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import {Query} from '@src/domain/models/query';
import type { IRequestTelcoOtpRepository } from '@src/domain/interfaces/card_dop/requestTelcoOtp';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import { RequestOtpDataReq } from '@src/domain/entities/card_dop/requestTelcoOtp';


export class RequestTelcoOtpHandler {
    private readonly _repository: IRequestTelcoOtpRepository;

    constructor(
        @inject(TYPES.IRequestTelcoOtpRepository)
        requestTelcoOtpRepository: IRequestTelcoOtpRepository,
    ) {
        this._repository = requestTelcoOtpRepository;
    }

    handle(query: Query<CardDOPBaseRequest<RequestOtpDataReq>>) {
        return this._repository.requestTelcoOtp(query);
    }
}
