import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_CARD_DOP_API } from '@src/config';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { IVerifyTelcoOtpRepository } from '@src/domain/interfaces/card_dop/verifyTelcoOtp';
import { VerifyTelcoOtpDataReq, VerifyTelcoOtpDataRes } from '@src/domain/entities/card_dop/verifyTelcoOtp';
import { commonService } from '@src/infrastructure/network/networkService';

@injectable()
export class VerifyTelcoOtpRepository
    extends HttpService
    implements IVerifyTelcoOtpRepository {
    constructor() {
        super({ baseURL: BASE_URL_CARD_DOP_API });
    }

    async verifyTelcoOtp<TParameter>(query: Query<TParameter>): Promise<CardDOPBaseResponse<VerifyTelcoOtpDataRes>> {
        const request = query.query as unknown as VerifyTelcoOtpDataReq;
        const url = '/dop-verify-telco-otp';
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-dop-mobile' }),
        })
        return response.data as CardDOPBaseResponse<VerifyTelcoOtpDataRes>;
    }
}
