import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import type { IDopCVPRepository } from '@src/domain/interfaces/cms/dop/dopCVP';

export class DopCVPHandler {
    private readonly _repository: IDopCVPRepository;

    constructor(
        @inject(TYPES.IDopCVPRepository)
        dopCVPRepository: IDopCVPRepository
    ) {
        this._repository = dopCVPRepository;
    }

    handle(segment: string) {
        return this._repository.getDopCVP(segment);
    }
}
