import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import {Query} from '@src/domain/models/query';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import type { ICardDetailsRepository } from '@src/domain/interfaces/card_dop/cardDetails';
import { CardDetailsDataReq } from '@src/domain/entities/card_dop/cardDetails';

export class CardDetailsHandler {
    private readonly _repository: ICardDetailsRepository;

    constructor(
        @inject(TYPES.ICardDetailsRepository)
        cardDetailsRepository: ICardDetailsRepository
    ) {
        this._repository = cardDetailsRepository;
    }

    handle(query: Query<CardDOPBaseRequest<CardDetailsDataReq>>) {
        return this._repository.cardDetails(query);
    }
}
