import { createSlice } from '@reduxjs/toolkit';
import { fetchGetCareersPositions } from '../thunk';
import { Career, Position } from '@src/domain/entities/card_dop/getCareersPositions';

export interface IStateSlice {
    status: 'idle' | 'loading' | 'succeeded' | 'failed';
    error: string;
    careers: Array<Career>;
    positions: Array<Position>;
}

const initialState: IStateSlice = {
    status: 'idle',
    error: '',
    careers: [],
    positions: [],
};

const Slice = createSlice({
    name: 'dop_confirm',
    initialState,
    reducers: {
        setError: (state, { payload }) => {
            state.error = payload;
        },
        setStatus: (state, { payload }) => {
            state.status = payload;
        },
    },
    extraReducers: (builder) => {
        builder
            .addCase(fetchGetCareersPositions.pending, (state) => {
                state.status = 'loading';
                state.error = '';
            })
            .addCase(fetchGetCareersPositions.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to fetch fetchGetCareersPositions';
            })
            .addCase(fetchGetCareersPositions.fulfilled, (state, { payload }) => {
                state.status = 'succeeded';
                if (!payload) {
                    state.error = 'Failed to fetch fetchGetCareersPositions because of payload undefined';
                    return;
                }
                state.error = '';

                const { data, resultCode, resultMessage } = payload;
                if (resultCode === '00') {
                    state.careers = data.careers;
                    state.positions = data.positions;
                } else {
                    state.error = resultMessage;
                }
            });
    },
});

export default Slice;
