import {
    useNavigation,
    NavigationProp,
    CommonActions,
    StackActions,
} from '@react-navigation/native';
import { MainStackParamList } from '@src/presentation/navigation/MainNavigator';

const useCustomNavigation = () => {
    const navigation = useNavigation<NavigationProp<MainStackParamList>>();

    const navigate = <RouteName extends keyof MainStackParamList>(
        name: RouteName,
        params?: MainStackParamList[RouteName],
    ) => {
        navigation.dispatch(
            CommonActions.navigate(name, { ...(params || {}), refresh: true }),
        );
    };

    const navigateAndReplace = <RouteName extends keyof MainStackParamList>(
        name: RouteName,
        params?: MainStackParamList[RouteName],
    ) => {
        navigation.dispatch(StackActions.replace(name, params));
    };

    const navigateAndReset = <RouteName extends keyof MainStackParamList>(
        name: RouteName,
        params?: MainStackParamList[RouteName],
    ) => {
        navigation.dispatch(
            CommonActions.reset({
                index: 0,
                routes: [{ name, params }],
            }),
        );
    };

    const goBackFromNativeModules = () => {
        const state = navigation.getState();
        const currentRoute = state?.routes[state?.index];
        if (currentRoute?.name) {
            navigate(currentRoute.name as keyof MainStackParamList);
        }
    };
    const goBack = () => {
        if (navigation.canGoBack()) {
            navigation.goBack();
        }
    };

    return { navigate, goBack, navigateAndReplace, navigateAndReset, goBackFromNativeModules };
};

export { useCustomNavigation };
