import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import type { IGetNfcImageRepository } from '@src/domain/interfaces/cms/dop/getNfcImage';

export class GetNfcImageHandler {
    private readonly _repository: IGetNfcImageRepository;

    constructor(
        @inject(TYPES.IGetNfcImageRepository)
        getNfcImageRepository: IGetNfcImageRepository
    ) {
        this._repository = getNfcImageRepository;
    }

    handle(name: string) {
        return this._repository.getNfcImage(name);
    }
}
