import { NativeModules, Platform } from 'react-native';
import { PERMISSIONS, RESULTS, check, request } from 'react-native-permissions';

const { ContactsModule } = NativeModules;

export type ContactResult = {
    name?: string;
    phoneNumber?: string;
    // Thêm các trường khác nếu cần
} | null;

type ContactCallback = (result: ContactResult) => void;

class ContactPickerService {
    private static instance: ContactPickerService;

    private constructor() {}

    public static getInstance(): ContactPickerService {
        if (!ContactPickerService.instance) {
            ContactPickerService.instance = new ContactPickerService();
        }
        return ContactPickerService.instance;
    }

    /**
     * Kiểm tra quyền truy cập danh bạ
     */
    private async checkContactsPermission(): Promise<boolean> {
        try {
            if (Platform.OS === 'android') {
                const permission = PERMISSIONS.ANDROID.READ_CONTACTS;
                const result = await check(permission);

                if (result === RESULTS.DENIED) {
                    const requestResult = await request(permission);
                    return requestResult === RESULTS.GRANTED;
                }

                return result === RESULTS.GRANTED;
            } else {
                const permission = PERMISSIONS.IOS.CONTACTS;
                const result = await check(permission);

                if (result === RESULTS.DENIED) {
                    const requestResult = await request(permission);
                    return requestResult === RESULTS.GRANTED;
                }

                return result === RESULTS.GRANTED;
            }
        } catch (error) {
            console.error('Error checking contacts permission:', error);
            return false;
        }
    }

    /**
     * Mở màn hình chọn contact của device
     */
    public async openContactPicker(onSelect: ContactCallback): Promise<void> {
        try {
            const hasPermission = await this.checkContactsPermission();
            if (!hasPermission) {
                throw new Error('Contacts permission not granted');
            }
            const result = await ContactsModule.openContacts();
            console.log('result', result);
            if (result) {
                onSelect({
                    name: result.name ?? '',
                    phoneNumber: result.number ?? '',
                });
            }
        } catch (error) {
            console.error('Error opening contact picker:', error);
            throw error;
        }
    }
}

export const contactPickerService = ContactPickerService.getInstance();
