import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_CARD_DOP_API } from '@src/config';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { RegisterUserDataReq, RegisterUserDataRes } from '@src/domain/entities/card_dop/registerUser';
import { IRegisterUserRepository } from '@src/domain/interfaces/card_dop/registerUser';

@injectable()
export class RegisterUserRepository extends HttpService implements IRegisterUserRepository {
    constructor() {
        super({ baseURL: BASE_URL_CARD_DOP_API });
    }

    async registerUser<TParameter>(query: Query<TParameter>): Promise<CardDOPBaseResponse<RegisterUserDataRes>> {
        const request = query.query as unknown as RegisterUserDataReq;
        const url = '/dop-register-user';
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-dop-mobile' }),
        });
        return response.data as CardDOPBaseResponse<RegisterUserDataRes>;
    }
}
