import { Query } from '@src/domain/models/query';
import { createAsyncThunk } from '@reduxjs/toolkit';
import { TYPES } from '@src/di/types/types';
import { container } from '@src/di/inversify.config';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { ValidateOcrHandler } from '@src/application/card_dop/validateOcr_handler';
import { ValidateOcrDataReq } from '@src/domain/entities/card_dop/validateOcr';
import { BiometricInfoDataReq } from '@src/domain/entities/card_dop/biometricInfo';
import { DopIDHandler } from '@src/application/card_dop/dopID_handler';
import { DopIDDataReq } from '@src/domain/entities/card_dop/dopID';
import { store } from '@src/lib/redux';
import { BiometricInfoHandler } from '@src/application/card_dop/biometricInfo_handler';
import { GetNfcImageHandler } from '@src/application/cms/dop/getNfcImage_handler';

export const fetchValidateOcr = createAsyncThunk('validateOcr/fetch', async (payload: CardDOPBaseRequest<ValidateOcrDataReq>['data']) => {
    console.log('\x1b[31m phapv7 thunk validateOcr: ', payload);
    const validateOcr = container.get<ValidateOcrHandler>(TYPES.ValidateOcrHandler);
    const payloadReq = commonService.getPayload<CardDOPBaseRequest<ValidateOcrDataReq>, CardDOPBaseRequest<ValidateOcrDataReq>['data']>({ data: payload })
    const query = new Query<CardDOPBaseRequest<ValidateOcrDataReq>>({
        query: {
            ...payloadReq,
            screenName: "MFE-DOP-OCRScreen",
        },
    });
    return await validateOcr.handle(query);
});

export const fetchBiometricInfo = createAsyncThunk('biometricInfo/fetch', async (payload?: CardDOPBaseRequest<BiometricInfoDataReq>['data']) => {
    const biometricInfo = container.get<BiometricInfoHandler>(TYPES.BiometricInfoHandler);
    const ICData = store?.getState?.()?.ocr?.ICData;
    const payloadReq = commonService.getPayload<CardDOPBaseRequest<BiometricInfoDataReq>, CardDOPBaseRequest<BiometricInfoDataReq>['data']>({ data: { idCardNo: ICData?.idNumber || payload?.idCardNo || '' } })
    const query = new Query<CardDOPBaseRequest<BiometricInfoDataReq>>({
        query: {
            ...payloadReq,
            screenName: "MFE-DOP-BackScreen",
        },
    });
    return await biometricInfo.handle(query);
});

export const fetchDopID = createAsyncThunk('dopId/fetch', async ({ payload, apiType }: { payload: CardDOPBaseRequest<DopIDDataReq>['data'], apiType: string }) => {
    const dopId = container.get<DopIDHandler>(TYPES.DopIDHandler);
    const payloadReq = commonService.getPayload<CardDOPBaseRequest<DopIDDataReq>, CardDOPBaseRequest<DopIDDataReq>['data']>({ data: payload })
    const query = new Query<CardDOPBaseRequest<DopIDDataReq>>({
        query: {
            ...payloadReq,
            screenName: "MFE-DOP-BackScreen",
        },
    });
    console.log('\x1b[31m thieuvq3 thunk apiType: ', apiType);
    return await dopId.handle(query, apiType);
});

export const fetchGetNfcImage = createAsyncThunk(
    'getNfcImage/fetch',
    async (name: string) => {                
        const getNfcImage = container.get<GetNfcImageHandler>(TYPES.GetNfcImageHandler);
        return await getNfcImage.handle(name);
    },
);